Contract ListBookHistory::listOverDueBook(uid:String): Set(BookCopy) {

            precondition:
          User.allInstances()->one(u: User|u.UserID = uid) and User.allInstances()->forAll(u: User|if u.UserID = uid then u.LoanedBook.oclIsUndefined() = false and u.LoanedBook->forAll(l: Loan|if l.IsReturned = false and l.OverDueFee > 0.0 then l.LoanedCopy.oclIsUndefined() = false else true endif) else true endif)

            postcondition:
          let u: User = User.allInstances()->any(x: User|x.UserID = uid) in result->forAll(c: BookCopy|u.LoanedBook->exists(l: Loan|l.IsReturned = false and l.OverDueFee > 0.0 and l.LoanedCopy = c)) and u.LoanedBook->forAll(l: Loan|if l.IsReturned = false and l.OverDueFee > 0.0 then result->exists(c: BookCopy|c = l.LoanedCopy) else true endif)

        }
